// Parser de mensajes entrantes de Evolution API
const item = $input.first();
if (!item || !item.json) return [];
const body = item.json.body || item.json;
const data = body.data || body;
if (!data) return [];

const SUPABASE_URL = 'https://petcqaixzetwsduscvtx.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM';

async function httpReq(url, options = {}) {
  const method = options.method || 'GET';
  const headers = options.headers || {};
  const reqBody = options.body;
  if (typeof $httpRequest === 'function') {
    return await $httpRequest({ method, url, headers, body: reqBody, json: true });
  }
  if (typeof fetch !== 'undefined') {
    const res = await fetch(url, { method, headers, body: reqBody ? (typeof reqBody === 'string' ? reqBody : JSON.stringify(reqBody)) : undefined });
    try { return await res.json(); } catch { return null; }
  }
  return null;
}

// BLOQUE 1: Mensajes salientes de la Secretaría (fromMe = true)
if (data.key && data.key.fromMe) {
  const remoteJid = data.key.remoteJid || '';
  if (remoteJid && !remoteJid.includes('@g.us') && !remoteJid.includes('status@broadcast')) {
    const patientPhone = remoteJid.replace('@s.whatsapp.net', '');
    let msgObj = data.message || {};
    if (msgObj.viewOnceMessage && msgObj.viewOnceMessage.message) msgObj = msgObj.viewOnceMessage.message;
    if (msgObj.viewOnceMessageV2 && msgObj.viewOnceMessageV2.message) msgObj = msgObj.viewOnceMessageV2.message;
    if (msgObj.ephemeralMessage && msgObj.ephemeralMessage.message) msgObj = msgObj.ephemeralMessage.message;
    let secText = '';
    if (msgObj.conversation) secText = msgObj.conversation;
    else if (msgObj.extendedTextMessage && msgObj.extendedTextMessage.text) secText = msgObj.extendedTextMessage.text;
    if (secText) {
      try {
        await httpReq(SUPABASE_URL + '/rest/v1/mensajes_chat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY },
          body: { whatsapp_id: patientPhone, emisor: 'SECRETARIA', contenido: secText }
        });
        await httpReq(SUPABASE_URL + '/rest/v1/pacientes_leads?whatsapp_id=eq.' + patientPhone, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json', 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY },
          body: { estado_atencion: 'ESCALADO_HUMANO', ultimo_mensaje: secText, updated_at: new Date().toISOString() }
        });
      } catch (err) {}
    }
  }
  return [];
}

// BLOQUE 2: Parsear remitente
const senderRemoteJid = (data.key && data.key.remoteJid) || '';
if (!senderRemoteJid || senderRemoteJid.includes('@g.us') || senderRemoteJid.includes('status@broadcast')) return [];

const senderPhone = senderRemoteJid.replace('@s.whatsapp.net', '');
const senderName = data.pushName || 'Paciente';
const instanceName = body.instance || 'gonzalez-prato';

// BLOQUE 3: Extraer texto
let msgObj = data.message || {};
if (msgObj.viewOnceMessage && msgObj.viewOnceMessage.message) msgObj = msgObj.viewOnceMessage.message;
if (msgObj.viewOnceMessageV2 && msgObj.viewOnceMessageV2.message) msgObj = msgObj.viewOnceMessageV2.message;
if (msgObj.ephemeralMessage && msgObj.ephemeralMessage.message) msgObj = msgObj.ephemeralMessage.message;
if (msgObj.documentWithCaptionMessage && msgObj.documentWithCaptionMessage.message) msgObj = msgObj.documentWithCaptionMessage.message;

let userText = '';
if (msgObj.conversation) userText = msgObj.conversation;
else if (msgObj.extendedTextMessage && msgObj.extendedTextMessage.text) userText = msgObj.extendedTextMessage.text;
else if (msgObj.imageMessage) userText = msgObj.imageMessage.caption || '[Foto de orden médica / récipe adjunta]';
else if (msgObj.audioMessage) userText = '[Nota de voz del paciente]';

if (!userText) return [];

// BLOQUE 4: Estado del bot (lead)
let leadStatus = 'BOT_ACTIVO';
try {
  const leadRows = await httpReq(
    SUPABASE_URL + '/rest/v1/pacientes_leads?whatsapp_id=eq.' + senderPhone + '&select=estado_atencion',
    { headers: { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY } }
  );
  if (Array.isArray(leadRows) && leadRows.length > 0 && leadRows[0].estado_atencion) {
    leadStatus = leadRows[0].estado_atencion;
  }
} catch(e) {}

const botActive = (leadStatus !== 'ESCALADO_HUMANO' && leadStatus !== 'FINALIZADO');

// BLOQUE 5: Horario laboral
const now = new Date();
const vzlaDate = new Date(now.toLocaleString('en-US', { timeZone: 'America/Caracas' }));
const dayOfWeek = vzlaDate.getDay();
const totalMinutes = vzlaDate.getHours() * 60 + vzlaDate.getMinutes();
let isOpen = false;
let nextOpening = 'Mañana a las 7:00 AM';
if (dayOfWeek >= 1 && dayOfWeek <= 5) {
  isOpen = totalMinutes >= 420 && totalMinutes < 900;
  if (!isOpen) nextOpening = totalMinutes < 420 ? 'Hoy a las 7:00 AM' : (dayOfWeek === 5 ? 'Sábado a las 8:00 AM' : 'Mañana a las 7:00 AM');
} else if (dayOfWeek === 6) {
  isOpen = totalMinutes >= 480 && totalMinutes < 780;
  if (!isOpen) nextOpening = totalMinutes < 480 ? 'Hoy a las 8:00 AM' : 'Lunes a las 7:00 AM';
} else {
  nextOpening = 'Lunes a las 7:00 AM';
}
const dayNames = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const currentDayName = dayNames[dayOfWeek];
const currentFormattedTime = vzlaDate.toLocaleTimeString('es-VE', { hour: '2-digit', minute: '2-digit', hour12: true });

// BLOQUE 6: System Prompt — SIN catálogo embebido (el agente usa la herramienta)
let p = 'Eres el Operador Principal y Asistente Clínico Virtual Oficial 24/7 de GONZALEZ-PRATO Laboratorio (Directora Técnica: Lic. Luisa Carolina González Ramírez, Mérida, Venezuela).\n\n';
p += 'CONTEXTO TEMPORAL ACTUAL (VENEZUELA):\n';
p += '- Hoy es: ' + currentDayName + ' | Hora: ' + currentFormattedTime + '\n';
p += '- Estado sede física: ' + (isOpen ? 'ABIERTO' : 'CERRADO. Próxima apertura: ' + nextOpening) + '\n';
p += '- Horario habitual: Lun-Vie 7:00 AM – 3:00 PM | Sáb 8:00 AM – 1:00 PM | Dom Cerrado.\n\n';
p += '══════════════════════════════════════════\n';
p += 'DIRECTIVA ABSOLUTA — CERO ALUCINACIONES DE PRECIOS\n';
p += '══════════════════════════════════════════\n';
p += '❌ NO tienes el tarifario en tu memoria. Está PROHIBIDO que inventes, estimes o recuerdes precios de memoria.\n';
p += '✅ ANTES de cotizar CUALQUIER examen, OBLIGATORIAMENTE debes invocar la herramienta "consultar_tarifario_supabase".\n';
p += '✅ Si el paciente pide 3 exámenes, invoca la herramienta 3 veces (una por examen).\n';
p += '✅ Si la herramienta devuelve múltiples variantes, usa el precio del registro más específico al nombre solicitado.\n';
p += '✅ Si la herramienta devuelve "No se encontraron resultados", responde TEXTUALMENTE: "Actualmente no dispongo del precio de este examen en mi base de datos. Por favor, aguarde un momento para que un operador humano le asista." y ejecuta "activar_human_handover_alarma".\n\n';
p += 'REGLAS INSTITUCIONALES:\n';
p += '- CULTIVOS GENÉRICOS: Si el paciente dice solo "un cultivo" sin especificar la muestra, usa la herramienta con "cultivo" y presenta las opciones disponibles con precios.\n';
p += '- EXÁMENES TORRE CARACAS: Si la herramienta devuelve costo $0.00 y menciona "Convenio Torre Caracas", informa que se remite a Caracas y ejecuta "activar_human_handover_alarma".\n';
p += '- MICOLOGÍA / DEMODEX: Requiere cita previa con la micóloga. Ejecuta "activar_human_handover_alarma".\n';
p += '- DOMICILIO: Disponible Lun, Mar y Jue. Gratis en Municipio Libertador.\n';
p += '- ENTREGAS: Rutina, química, hematología, hormonas y serología: MISMO DÍA. Cultivos: 3-8 días.\n';
p += '- SEGUROS: No hay convenio. Se emite factura para reembolso.\n';
p += '- HECES: Recepción Lun-Vie hasta 2:30 PM | Sáb hasta 12:30 PM.\n';
p += '- NO REALIZAMOS: Ecografías, radiografías, biopsias, endoscopias ni citas médicas.\n';
p += '- ESCALADO: Si el paciente pide "secretaria", "persona", "humano", hace un reclamo o pide domicilio, ejecuta "activar_human_handover_alarma".\n\n';
p += 'FORMATO DE COTIZACIÓN OBLIGATORIO (usa EXACTAMENTE los datos de la herramienta):\n';
p += '• [Nombre del Examen]\n  - Precio: $[Monto exacto de la herramienta] USD\n  - Muestra: [De la herramienta]\n  - Requisitos: [De la herramienta]\n\n';
p += '──────────────────────────\n';
p += 'Total a Cancelar: $[Suma exacta] USD\n';
p += '(Aceptamos Bolívares a tasa BCV, Pago Móvil, Punto de Venta, Transferencia y Efectivo)\n\n';
p += '📍 Sede: Urb. El Encanto, Clínica del Niño, Sótano 2 (detrás de la Contraloría del Estado Mérida).\n';
p += '⏰ Horarios: Lun-Vie 7:00 AM – 3:00 PM | Sáb 8:00 AM – 1:00 PM.';

return [{
  json: {
    senderRemoteJid, senderPhone, senderName, userText,
    instance: instanceName, leadStatus, botActive,
    completeSystemPrompt: p,
    scheduleContext: { isOpen, nextOpening, currentDayName, currentFormattedTime }
  }
}];

const senderPhone = $('Parsear Mensaje Evolution API').first().json.senderPhone || $json.senderPhone;
const scheduleCtx = $('Parsear Mensaje Evolution API').first().json.scheduleContext || {};
const estadoAtencion = (scheduleCtx && scheduleCtx.isOpen) ? 'ESCALADO_HUMANO' : 'ESCALADO_FUERA_HORARIO';
const KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM';
try {
  await $httpRequest({
    method: 'PATCH',
    url: 'https://petcqaixzetwsduscvtx.supabase.co/rest/v1/pacientes_leads?whatsapp_id=eq.' + senderPhone,
    headers: { 'Content-Type': 'application/json', 'apikey': KEY, 'Authorization': 'Bearer ' + KEY },
    body: { estado_atencion: estadoAtencion, updated_at: new Date().toISOString() },
    json: true
  });
} catch (err) {}
return JSON.stringify({
  status: 'handover_triggered',
  estado_registrado: estadoAtencion,
  mensaje: estadoAtencion === 'ESCALADO_HUMANO' ? 'Alarma activada en recepción.' : 'Registrado. Atención a primera hora hábil.'
});

// Extraer el parámetro de búsqueda enviado por el Agente
let query = '';
try {
  const raw = $input.item;
  if (typeof raw === 'string') { query = raw; }
  else if (raw && typeof raw === 'object') {
    query = raw.query || raw.termino || raw.examen || raw.term || raw.nombre || raw.input || Object.values(raw)[0] || '';
  }
  query = String(query).trim();
} catch(e) { query = ''; }

if (!query) return 'Error: debes enviar el nombre del examen como parámetro. Ejemplo: glicemia, prolactina, hematologia.';

const KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM';
const url = 'https://petcqaixzetwsduscvtx.supabase.co/rest/v1/examenes?activo=eq.true&nombre_examen=ilike.%25' + encodeURIComponent(query) + '%25&select=categoria,nombre_examen,sinonimos,costo_usd,requisitos_preanaliticos,tipo_muestra,notas&limit=6';

try {
  let data;
  if (typeof $httpRequest === 'function') {
    data = await $httpRequest({ method: 'GET', url, headers: { 'apikey': KEY, 'Authorization': 'Bearer ' + KEY }, json: true });
  } else if (typeof fetch !== 'undefined') {
    const res = await fetch(url, { headers: { 'apikey': KEY, 'Authorization': 'Bearer ' + KEY } });
    data = await res.json();
  } else {
    return 'Error: no hay cliente HTTP disponible. Activa el protocolo de handover humano.';
  }

  if (!Array.isArray(data) || data.length === 0) {
    return 'No se encontraron resultados en la base de datos oficial para: "' + query + '". Activa el protocolo de handover humano.';
  }

  // Deduplicar por nombre_examen + costo_usd
  const seen = new Set();
  const unique = data.filter(e => {
    const key = e.nombre_examen + '|' + e.costo_usd;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  return unique.map(e => {
    const cost = Number(e.costo_usd);
    const syn = Array.isArray(e.sinonimos) && e.sinonimos.length > 0 ? ' (También conocido como: ' + e.sinonimos.join(', ') + ')' : '';
    const notes = e.notas ? ' | NOTA CLÍNICA: ' + e.notas : '';
    return 'EXAMEN OFICIAL: ' + e.nombre_examen + syn +
           ' | CATEGORÍA: ' + (e.categoria || 'General') +
           ' | PRECIO OFICIAL: $' + cost.toFixed(2) + ' USD' +
           ' | MUESTRA: ' + (e.tipo_muestra || 'Sangre venosa') +
           ' | REQUISITOS: ' + (e.requisitos_preanaliticos || 'Sin requisitos especiales') +
           notes;
  }).join('\n---\n');

} catch(e) {
  return 'Error de red al consultar Supabase: ' + (e.message || e) + '. Activa el protocolo de handover humano.';
}
